function guiScript(): string {
  const seats = computeParliamentSeats({ crown: 12, chamber: 9, independents: 4 }, 80, 100, 100);
  const dots: GuiElementDef[] = seats.dots.map((d, i) => ({
    id: `seat_${i}`,
    type: 'iconType',
    name: `GDX_seat_${i}`,
    position: { x: d.x, y: d.y },
    size: { width: 8, height: 8 },
    spriteType: 'GFX_tiled_window_thin_border',
  }));
  const root: GuiElementDef = {
    id: 'root',
    type: 'containerWindowType',
    name: 'GDX_parliament_window',
    position: { x: 100, y: 100 },
    size: { width: 220, height: 140 },
    orientation: 'upper_left',
    children: dots,
  };
  return 'guiTypes = {' + String.fromCharCode(10) + serializeGuiElement(root, 1) + String.fromCharCode(10) + '}' + String.fromCharCode(10);
}

